import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        // Greedy: extend the current segment until a character repeats, then cut before it.
        boolean[] seen = new boolean[128];
        int answer = 1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (seen[c]) {
                answer++;
                Arrays.fill(seen, false);
            }
            seen[c] = true;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	// Greedy: extend the current segment until a character repeats, then cut before it.
	var seen [256]bool
	answer := 1
	for i := 0; i < len(s); i++ {
		if seen[s[i]] {
			answer++
			seen = [256]bool{}
		}
		seen[s[i]] = true
	}
	fmt.Println(answer)
}
